using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEditor;using System;using System.Threading.Tasks;using System.Reflection;
public class ForgeImeProbeInput:BaseInput {public string preedit="";public override string compositionString=>preedit;}
public static class ForgeImeCommitChecks{
 public static async Task<string> Run(){
 var module=EventSystem.current.currentInputModule;var previous=module.inputOverride;var root=new GameObject("IME regression",typeof(RectTransform),typeof(Canvas));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;
 var fake=root.AddComponent<ForgeImeProbeInput>();module.inputOverride=fake;bool bg=Application.runInBackground;Application.runInBackground=true;
 try{var go=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UI/ForgeCodeWindow.prefab"),root.transform);go.SetActive(true);ForgeLegacyUIFont.Apply(go.transform);var field=go.GetComponent<ForgeCodeView>().editor;field.onValueChanged=new InputField.OnChangeEvent();field.text="m = 1(1) #\n2(m)\n3(m)\n4(m, 0)\n5(m, 1)\n!m";field.ActivateInputField();await Task.Delay(100);field.caretPosition=10;
 string expected=field.text;int pos=10;string report="";string commits="안녕하세요";string[] preedits={"ㅇ","아","안","ㄴ","녀","녕","ㅎ","하","ㅅ","세","ㅇ","요"};foreach(var part in preedits){fake.preedit=part;field.ForceLabelUpdate();if(field.text!=expected)throw new Exception("Preedit changed source");}
 for(int n=0;n<commits.Length;n++){fake.preedit=n==commits.Length-1?"":"ㄴ";field.ProcessEvent(new Event{type=EventType.KeyDown,character=commits[n]});expected=expected.Insert(pos++,commits[n].ToString());await Task.Delay(30);report+="commit="+commits[n]+" raw="+typeof(InputField).GetField("m_CaretPosition",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(field)+" text="+field.text.Replace("\n","|")+"\n";}
 fake.preedit="";field.ForceLabelUpdate();if(field.text!=expected)throw new Exception("IME commit changed another line: "+report);report+="PASS sequential IME commits preserve every source line\n";
field.text="m = 1(1) #ABC\n2(m)";field.selectionAnchorPosition=10;field.selectionFocusPosition=13;fake.preedit="ㄴ";field.ProcessEvent(new Event{type=EventType.KeyDown,character='안'});fake.preedit="";field.ForceLabelUpdate();if(field.text!="m = 1(1) #안\n2(m)")throw new Exception("IME replacement used display indices: "+field.text);report+="PASS IME selection replacement uses committed-text indices\n";System.IO.File.WriteAllText("Docs/CodeWindowFeedback/ime-commit-check.txt",report);return report;
 }finally{module.inputOverride=previous;UnityEngine.Object.DestroyImmediate(root);Application.runInBackground=bg;}}
}
